"""Prove the structural correspondence between a slide's OOXML and rendered SVG."""

from dataclasses import dataclass
from enum import StrEnum
from math import hypot
from re import fullmatch
from typing import Literal, assert_never

from lxml import etree

from impromptu_ingestion.contracts import ContractModel
from impromptu_ingestion.render.contracts import MappingIssue, ResolvedTarget

_MAX_NODES = 50_000
_MAX_DEPTH = 64
_CENTER_TOLERANCE = 150.0
_IGNORED_CLASSES = frozenset(
    {"Background", "BackgroundObjects", "DateTime", "Footer", "PageNumber", "Header"}
)
_SIMPLE_CLASSES = frozenset({"Group", "Graphic", "TitleText", "Outline", "Subtitle", "Body"})
_ID_PATTERN = r"[A-Za-z][A-Za-z0-9_.:-]{0,127}"


class SlideMapping(ContractModel):
    """Resolved animation targets and all structural disagreements for one slide."""

    slide_index: int
    targets: tuple[ResolvedTarget, ...]
    issues: tuple[MappingIssue, ...]


class MappingParseError(ValueError):
    """A bounded, machine-readable failure to parse renderer input."""

    code: Literal["invalid_slide_xml", "invalid_slide_svg", "xml_limit_exceeded"]

    def __init__(
        self,
        code: Literal["invalid_slide_xml", "invalid_slide_svg", "xml_limit_exceeded"],
        detail: str,
    ) -> None:
        self.code = code
        super().__init__(detail)


class _ShapeKind(StrEnum):
    AUTO_SHAPE = "CustomShape"
    GROUP = "Group"
    PICTURE = "Graphic"
    LINE = "ConnectorShape"
    TABLE = "TableShape"


@dataclass(frozen=True)
class _Transform:
    sx: float = 1.0
    sy: float = 1.0
    tx: float = 0.0
    ty: float = 0.0

    def point(self, x: float, y: float) -> tuple[float, float]:
        return (self.tx + self.sx * x, self.ty + self.sy * y)


@dataclass(frozen=True)
class _OoxmlShape:
    shape_id: int
    name: str
    kind: _ShapeKind
    expected_class: str
    center: tuple[float, float]
    children: tuple["_OoxmlShape", ...] = ()


@dataclass(frozen=True)
class _SvgShape:
    element: etree._Element
    class_name: str
    center: tuple[float, float]
    children: tuple["_SvgShape", ...] = ()


@dataclass
class _ParseState:
    placeholder_count: int = 0


def _parse_xml(source: bytes | str, code: Literal["invalid_slide_xml", "invalid_slide_svg"]) -> etree._Element:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, huge_tree=False)
    try:
        root = etree.fromstring(source, parser)
    except (etree.XMLSyntaxError, ValueError, TypeError) as error:
        raise MappingParseError(code, str(error)) from error
    count = 0
    stack: list[tuple[etree._Element, int]] = [(root, 1)]
    while stack:
        element, depth = stack.pop()
        count += 1
        if count > _MAX_NODES or depth > _MAX_DEPTH:
            raise MappingParseError("xml_limit_exceeded", "XML exceeds mapping safety limits")
        stack.extend((child, depth + 1) for child in element)
    return root


def _local(element: etree._Element) -> str:
    return etree.QName(element).localname


def _child(element: etree._Element, local_name: str) -> etree._Element | None:
    return next((item for item in element if _local(item) == local_name), None)


def _descendant(element: etree._Element, local_name: str) -> etree._Element | None:
    return next((item for item in element.iter() if _local(item) == local_name), None)


def _numbers(xfrm: etree._Element) -> tuple[float, float, float, float]:
    off, ext = _child(xfrm, "off"), _child(xfrm, "ext")
    if off is None or ext is None:
        raise MappingParseError("invalid_slide_xml", "shape transform lacks offset or extent")
    try:
        return tuple(float(value) for value in (off.get("x"), off.get("y"), ext.get("cx"), ext.get("cy")))  # type: ignore[return-value]
    except (TypeError, ValueError) as error:
        raise MappingParseError("invalid_slide_xml", "shape transform has invalid coordinates") from error


def _kind(element: etree._Element) -> _ShapeKind:
    match _local(element):
        case "sp":
            return _ShapeKind.AUTO_SHAPE
        case "grpSp":
            return _ShapeKind.GROUP
        case "pic":
            return _ShapeKind.PICTURE
        case "cxnSp":
            return _ShapeKind.LINE
        case "graphicFrame":
            if _descendant(element, "tbl") is not None:
                return _ShapeKind.TABLE
            raise MappingParseError("invalid_slide_xml", "unsupported non-table graphicFrame")
        case unknown:
            raise MappingParseError("invalid_slide_xml", f"unsupported shape element {unknown}")


def _xfrm(element: etree._Element, kind: _ShapeKind) -> etree._Element:
    match kind:
        case _ShapeKind.GROUP:
            properties = _child(element, "grpSpPr")
        case _ShapeKind.AUTO_SHAPE | _ShapeKind.PICTURE | _ShapeKind.LINE:
            properties = _child(element, "spPr")
        case _ShapeKind.TABLE:
            properties = element
        case unreachable:
            assert_never(unreachable)
    transform = None if properties is None else _descendant(properties, "xfrm")
    if transform is None:
        raise MappingParseError("invalid_slide_xml", "shape lacks a transform")
    return transform


def _ooxml_shapes(parent: etree._Element, transform: _Transform, state: _ParseState) -> tuple[_OoxmlShape, ...]:
    result: list[_OoxmlShape] = []
    for element in parent:
        if _local(element) not in {"sp", "grpSp", "pic", "cxnSp", "graphicFrame"}:
            continue
        properties = _descendant(element, "cNvPr")
        if properties is None:
            raise MappingParseError("invalid_slide_xml", "shape lacks non-visual properties")
        if properties.get("hidden") == "1":
            continue
        kind = _kind(element)
        x, y, width, height = _numbers(_xfrm(element, kind))
        center = transform.point(x + width / 2, y + height / 2)
        placeholder = _descendant(element, "ph") is not None
        if placeholder:
            expected = "TitleText" if state.placeholder_count == 0 else "Outline"
            state.placeholder_count += 1
        else:
            expected = kind.value
        children: tuple[_OoxmlShape, ...] = ()
        if kind is _ShapeKind.GROUP:
            group_xfrm = _xfrm(element, kind)
            child_off, child_ext = _child(group_xfrm, "chOff"), _child(group_xfrm, "chExt")
            if child_off is None or child_ext is None:
                raise MappingParseError("invalid_slide_xml", "group transform lacks child coordinates")
            try:
                cx, cy = float(child_off.get("x")), float(child_off.get("y"))
                cw, ch = float(child_ext.get("cx")), float(child_ext.get("cy"))
                child_transform = _Transform(
                    transform.sx * width / cw,
                    transform.sy * height / ch,
                    transform.tx + transform.sx * x - transform.sx * width * cx / cw,
                    transform.ty + transform.sy * y - transform.sy * height * cy / ch,
                )
            except (TypeError, ValueError, ZeroDivisionError) as error:
                raise MappingParseError("invalid_slide_xml", "group child transform is invalid") from error
            children = _ooxml_shapes(element, child_transform, state)
        result.append(
            _OoxmlShape(int(properties.get("id", "0")), properties.get("name", ""), kind, expected, center, children)
        )
    return tuple(result)


def _svg_class(element: etree._Element) -> str | None:
    value = element.get("class", "")
    if value.startswith("com.sun.star."):
        return value.rsplit(".", 1)[-1]
    return value if value in _SIMPLE_CLASSES else None


def _svg_center(element: etree._Element, class_name: str) -> tuple[float, float]:
    rects = [item for item in element.iter() if _local(item) == "rect" and item.get("class") == "BoundingBox"]
    if not rects:
        raise MappingParseError("invalid_slide_svg", f"{class_name} container lacks BoundingBox")
    selected = rects if class_name in _SIMPLE_CLASSES else rects[:1]
    try:
        boxes = [(float(rect.get("x")), float(rect.get("y")), float(rect.get("width")), float(rect.get("height"))) for rect in selected]
    except (TypeError, ValueError) as error:
        raise MappingParseError("invalid_slide_svg", "BoundingBox has invalid coordinates") from error
    left = min(x for x, _, _, _ in boxes)
    top = min(y for _, y, _, _ in boxes)
    right = max(x + width for x, _, width, _ in boxes)
    bottom = max(y + height for _, y, _, height in boxes)
    return ((left + right) / 2, (top + bottom) / 2)


def _svg_shapes(parent: etree._Element) -> tuple[_SvgShape, ...]:
    result: list[_SvgShape] = []
    for element in parent:
        class_name = _svg_class(element)
        if class_name is None or class_name in _IGNORED_CLASSES:
            continue
        children = _svg_shapes(element) if class_name == "Group" else ()
        result.append(_SvgShape(element, class_name, _svg_center(element, class_name), children))
    return tuple(result)


def _element_id(element: etree._Element) -> str | None:
    for candidate in element.iter():
        value = candidate.get("id") if _local(candidate) == "g" else None
        if value is not None and fullmatch(_ID_PATTERN, value) is not None:
            return value
    return None


def map_slide(slide_xml: bytes, slide_svg: str, slide_index: int) -> SlideMapping:
    """Map OOXML shapes to SVG containers while recording every disagreement."""
    xml_root = _parse_xml(slide_xml, "invalid_slide_xml")
    svg_root = _parse_xml(slide_svg, "invalid_slide_svg")
    shape_tree = _descendant(xml_root, "spTree")
    page = next((item for item in svg_root.iter() if _local(item) == "g" and item.get("class") == "Page"), None)
    if shape_tree is None or page is None:
        code = "invalid_slide_xml" if shape_tree is None else "invalid_slide_svg"
        raise MappingParseError(code, "input lacks a shape tree or SVG Page container")
    source = _ooxml_shapes(shape_tree, _Transform(), _ParseState())
    rendered = _svg_shapes(page)
    targets: list[ResolvedTarget] = []
    issues: list[MappingIssue] = []

    def compare(left: tuple[_OoxmlShape, ...], right: tuple[_SvgShape, ...], path: str) -> None:
        if len(left) != len(right):
            code = "top_level_count_mismatch" if path == f"slide{slide_index}" else "child_count_mismatch"
            issues.append(MappingIssue(code=code, slide_index=slide_index, path=path, detail=f"OOXML has {len(left)} containers; SVG has {len(right)}"))
        for index, (shape, container) in enumerate(zip(left, right, strict=False)):
            item_path = f"{path}.{index}"
            if shape.expected_class != container.class_name:
                issues.append(MappingIssue(code="type_mismatch", slide_index=slide_index, path=item_path, detail=f"OOXML {shape.name} expects {shape.expected_class}; SVG has {container.class_name}"))
            source_center = (shape.center[0] / 360, shape.center[1] / 360)
            if hypot(source_center[0] - container.center[0], source_center[1] - container.center[1]) > _CENTER_TOLERANCE:
                issues.append(MappingIssue(code="center_mismatch", slide_index=slide_index, path=item_path, detail=f"OOXML {shape.name} center {source_center}; SVG {container.class_name} center {container.center}"))
            element_id = _element_id(container.element)
            if element_id is None:
                issues.append(MappingIssue(code="missing_element_id", slide_index=slide_index, path=item_path, detail=f"OOXML {shape.name}; SVG {container.class_name} has no usable element id"))
            else:
                targets.append(ResolvedTarget(shape_id=shape.shape_id, shape_name=shape.name, svg_element_id=element_id))
            if shape.kind is _ShapeKind.GROUP:
                compare(shape.children, container.children, item_path)

    compare(source, rendered, f"slide{slide_index}")
    return SlideMapping(slide_index=slide_index, targets=tuple(targets), issues=tuple(issues))

